import { useEffect, useRef, useContext } from 'react';
import { ThemeContext } from '../context/ThemeContext';
import { readViewportHeight } from './rain-study/useViewportHeight';

const ImprovedLetterRain = ({ paused = false }) => {
  const canvasRef = useRef(null);
  const impactRef = useRef(null);
  const { darkMode } = useContext(ThemeContext);
  const pausedRef = useRef(paused); pausedRef.current = paused;
  const engineRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const rainContext = canvas.getContext('2d');
    const impactCanvas = impactRef.current;
    const impactContext = impactCanvas.getContext('2d');
    if (!rainContext || !impactContext) return undefined;
    // The original drawing classes use ctx. Switching it between render passes
    // preserves their exact paint math while lifting only impacts above content.
    let ctx = rainContext;
    let animationFrameId;
    const delayedRipples = new Set();
    const fontSize = 14;
    let columns = 0;

    // Set canvas size
    const resizeCanvas = () => {
      const height=readViewportHeight();
      if(height===null)return;
      canvas.width = window.innerWidth;
      canvas.height = height;
      impactCanvas.width = canvas.width;
      impactCanvas.height = Math.min(144, canvas.height);
      impactContext.setTransform(1, 0, 0, 1, 0, -(canvas.height - impactCanvas.height));
      columns = Math.ceil(canvas.width / fontSize);
    };
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    window.visualViewport?.addEventListener('resize',resizeCanvas);

    // Characters - mix of tech symbols, numbers, and select letters
    const chars = '01アイウエオカキクケコサシスセソタチツテト0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ@#$%^&*';

    // Splash particle class for impact effects
    class SplashParticle {
      constructor(x, y, color) {
        this.x = x;
        this.y = y;
        this.vx = (Math.random() - 0.5) * 4; // Horizontal velocity
        this.vy = -Math.random() * 6 - 2; // Upward velocity
        this.gravity = 0.3;
        this.life = 1;
        this.decay = 0.02;
        this.size = Math.random() * 3 + 1;
        this.color = color;
      }

      update() {
        this.x += this.vx;
        this.y += this.vy;
        this.vy += this.gravity;
        this.life -= this.decay;
        this.vx *= 0.98; // Air resistance
      }

      draw() {
        ctx.save();
        ctx.globalAlpha = this.life;
        ctx.fillStyle = `${this.color}, ${this.life})`;
        ctx.shadowBlur = 10;
        ctx.shadowColor = `${this.color}, ${this.life * 0.5})`;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    }

    // Ripple class for water rings
    class Ripple {
      constructor(x, y, color) {
        this.x = x;
        this.y = y;
        this.radius = 0;
        this.maxRadius = Math.random() * 30 + 20;
        this.life = 1;
        this.decay = 0.02;
        this.color = color;
        this.lineWidth = 2;
      }

      update() {
        this.radius += 2;
        this.life -= this.decay;
        this.lineWidth = Math.max(0.5, this.lineWidth - 0.05);
      }

      draw() {
        ctx.save();
        ctx.globalAlpha = this.life * 0.3;
        ctx.strokeStyle = `${this.color}, ${this.life})`;
        ctx.lineWidth = this.lineWidth;
        ctx.shadowBlur = 15;
        ctx.shadowColor = `${this.color}, ${this.life * 0.3})`;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }
    }

    // Drop class for firefly effect
    class Drop {
      constructor(x, startFromTop = false) {
        this.x = x;
        // Always start from above the screen, or spread if initializing
        if (startFromTop) {
          this.y = -Math.random() * 50; // Start just above screen
        } else {
          // Initial spread for page load only
          this.y = Math.random() * (canvas.height * 2) - canvas.height;
        }
        this.speed = Math.random() * 2.0 + 1.5; // Moderate speed: 1.5-3.5
        this.char = chars[Math.floor(Math.random() * chars.length)];
        this.opacity = darkMode ? Math.random() * 0.4 + 0.35 : Math.random() * 0.3 + 0.25;
        this.glowIntensity = 0.75; // Slightly stronger glow
        this.color = this.getColor();
        this.changeInterval = Math.floor(Math.random() * 20) + 10;
        this.frameCount = 0;
        this.hasSplashed = false; // Track if this drop has already splashed
      }

      getColor() {
        const darkColors = [
          'rgba(255, 235, 180', // Soft luminous gold
          'rgba(255, 220, 155', // Warm amber
          'rgba(255, 255, 210', // Pale glow
          'rgba(255, 210, 140', // Honey light
        ];

        const lightColors = [
          'rgba(200, 140, 35',  // Rich bronze-gold
          'rgba(185, 120, 25',  // Deep amber
          'rgba(210, 150, 45',  // Goldenrod
          'rgba(170, 110, 30',  // Burnished copper
        ];

        const colors = darkMode ? darkColors : lightColors;
        return colors[Math.floor(Math.random() * colors.length)];
      }

      update() {
        this.y += this.speed;
        this.frameCount++;

        // Change character periodically
        if (this.frameCount % this.changeInterval === 0) {
          this.char = chars[Math.floor(Math.random() * chars.length)];
        }

        // Don't reset - let them be removed and new ones created
      }

      draw() {
        const alpha = this.opacity;

        // Reset shadow from previous draws
        ctx.shadowBlur = 0;
        ctx.shadowColor = 'transparent';

        // Subtle glow effect
        ctx.shadowBlur = 12;
        ctx.shadowColor = `${this.color}, ${alpha * 0.5})`;

        // Draw character
        ctx.fillStyle = `${this.color}, ${alpha})`;
        ctx.font = `${fontSize}px monospace`;
        ctx.fillText(this.char, this.x * fontSize, this.y);

        // Reset shadow after character
        ctx.shadowBlur = 0;

        // Small glow dot
        ctx.beginPath();
        ctx.arc(this.x * fontSize + fontSize/2, this.y - 2, 1.5, 0, Math.PI * 2);
        ctx.fillStyle = `${this.color}, ${alpha})`;
        ctx.fill();
      }
    }

    // Create drops (heavy rain)
    const drops = [];
    const splashParticles = [];
    const ripples = [];
    const dropCount = Math.floor(columns * 1.2); // 120% density - very heavy rain

    for (let i = 0; i < dropCount; i++) {
      drops.push(new Drop(Math.floor(Math.random() * columns)));
    }

    // Create splash effect
    const createSplash = (x, y, color) => {
      // Create multiple splash particles
      const particleCount = Math.floor(Math.random() * 5) + 3;
      for (let i = 0; i < particleCount; i++) {
        splashParticles.push(new SplashParticle(x, y, color));
      }

      // Create ripples
      ripples.push(new Ripple(x, y, color));

      // Occasionally create a second ripple for depth
      if (Math.random() > 0.5) {
        const timer = setTimeout(() => {
          delayedRipples.delete(timer);
          if (!pausedRef.current) ripples.push(new Ripple(x, y, color));
        }, 100);
        delayedRipples.add(timer);
      }
    };

    // Animation loop
    let frameCounter = 0;
    const animate = () => {
      ctx = rainContext;
      // Fade out trails - match background color based on theme
      const trailOpacity = darkMode ? 0.45 : 0.55;
      if (darkMode) {
        // Dark theme: #1A1410 = rgb(26, 20, 16)
        ctx.fillStyle = `rgba(26, 20, 16, ${trailOpacity})`;
      } else {
        // Light theme: #FDFBF7 = rgb(253, 251, 247)
        ctx.fillStyle = `rgba(253, 251, 247, ${trailOpacity})`;
      }
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Fade the transparent foreground by the original trail amount. Unlike
      // painting the background color, this cannot dim cards or footer links.
      impactContext.save();
      impactContext.globalCompositeOperation = 'destination-out';
      impactContext.fillStyle = `rgba(0, 0, 0, ${trailOpacity})`;
      impactContext.fillRect(0, canvas.height - impactCanvas.height, canvas.width, impactCanvas.height);
      impactContext.restore();

      // Add new drops at a sustainable rate
      frameCounter++;
      if (frameCounter % 2 === 0 && drops.length < columns * 1.5) {
        // Add 5 drops every other frame, always starting from top
        for (let i = 0; i < 5; i++) {
          drops.push(new Drop(Math.floor(Math.random() * columns), true));
        }
      }

      // Update and draw ripples (draw first for layering)
      ctx = impactContext;
      for (let i = ripples.length - 1; i >= 0; i--) {
        ripples[i].update();
        ripples[i].draw();

        // Remove dead ripples
        if (ripples[i].life <= 0 || ripples[i].radius > ripples[i].maxRadius) {
          ripples.splice(i, 1);
        }
      }

      // Update and draw drops
      ctx = rainContext;
      for (let i = drops.length - 1; i >= 0; i--) {
        drops[i].update();
        drops[i].draw();

        // Check if drop hits the bottom and create splash
        if (!drops[i].hasSplashed && drops[i].y > canvas.height - 20 && drops[i].y < canvas.height + 10) {
          drops[i].hasSplashed = true;
          // Create splash at the drop position
          createSplash(drops[i].x * fontSize + fontSize/2, canvas.height - 10, drops[i].color);
        }

        // Remove drops that are off screen (cleanup) - iterate backwards
        if (drops[i].y > canvas.height + 100) {
          drops.splice(i, 1);
        }
      }

      // Update and draw splash particles
      ctx = impactContext;
      for (let i = splashParticles.length - 1; i >= 0; i--) {
        splashParticles[i].update();
        splashParticles[i].draw();

        // Remove dead particles
        if (splashParticles[i].life <= 0) {
          splashParticles.splice(i, 1);
        }
      }

      ctx = rainContext;
      if (!pausedRef.current) animationFrameId = requestAnimationFrame(animate);
    };

    const stop = () => { cancelAnimationFrame(animationFrameId); delayedRipples.forEach(clearTimeout); delayedRipples.clear(); };
    engineRef.current = { start: () => { cancelAnimationFrame(animationFrameId); animationFrameId = requestAnimationFrame(animate); }, stop };
    animate();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      window.visualViewport?.removeEventListener('resize',resizeCanvas);
      stop(); engineRef.current = null;
    };
  }, [darkMode]);

  useEffect(() => { if (paused) engineRef.current?.stop(); else engineRef.current?.start(); return () => engineRef.current?.stop(); }, [paused, darkMode]);

  return (
    <><canvas
      ref={canvasRef}
      data-effect="original-letter-rain"
      data-active={!paused}
      aria-hidden="true"
      className="fixed top-0 left-0 w-full h-full pointer-events-none z-0 blur-[2px]"
      style={{ height:'var(--rain-viewport-height, 100%)', opacity: darkMode ? 0.5 : 0.65 }}
    /><canvas
      ref={impactRef}
      data-effect="original-rain-impact"
      data-active={!paused}
      aria-hidden="true"
      className="fixed bottom-0 left-0 w-full pointer-events-none z-20 blur-[2px]"
      style={{ height: 'min(144px, var(--rain-viewport-height, 100dvh))', opacity: darkMode ? 0.5 : 0.65 }}
    /></>
  );
};

export default ImprovedLetterRain;
